from flask import request, send_file, Flask
import os

app = Flask(__name__)

@app.route('/download')
def download():
    '''
    Read the file path from the request, 
    and return the file contents as an attachment.
    '''
    # Get the file path from the query parameters
    file_path = request.args.get('file')

    # Define a base directory for allowed files
    BASE_DIR = './files'

    # Ensure the file path is within the allowed directory
    if not os.path.isabs(file_path):
        full_path = os.path.join(BASE_DIR, file_path)
    else:
        full_path = file_path

    # Check for path traversal attempts
    if '../' in full_path:
        return "Forbidden", 403

    # Ensure the file exists and is within the allowed directory
    if not os.path.exists(full_path) or not full_path.startswith(BASE_DIR):
        return "File not found", 404

    try:
        return send_file(full_path)
    except FileNotFoundError:
        return "File not found", 404

